// ═══ Optional.of() — ASSERTION: value must be non-null ═══
String accountId = "SAV2001";           // definitely not null
Optional<String> opt = Optional.of(accountId);  // (Recommended) OK

String maybeNull = null;
// Optional.of(maybeNull);             //  NullPointerException!
// Use this when null means YOUR CODE has a bug

// ═══ Optional.ofNullable() — WRAPPING: null is fine ═══
String fromDb = repository.findName("SAV2001");  // might return null
Optional<String> opt = Optional.ofNullable(fromDb);
// null → Optional.empty()
// "Rajesh" → Optional.of("Rajesh")

// ═══ When to use which ═══

// Service layer — you CONTROL the value:
Trade trade = tradeRepo.save(newTrade);    // save() never returns null
Optional<Trade> opt = Optional.of(trade);   // of() — null would be a JPA bug

// External data — you DON'T control the value:
String phone = customer.getPhone();         // phone might be null in DB
Optional<String> opt = Optional.ofNullable(phone);  // ofNullable() — null is valid

// Method return — converting nullable to Optional:
public Optional<Account> findAccount(String id) {
    Account account = legacyDao.find(id);    // legacy method returns null
    return Optional.ofNullable(account);      // convert null → empty
}
