package com.bank.profile.service;

import com.bank.profile.dto.CustomerProfile;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.Optional;

@Service
@Slf4j
public class ProfileService {

    // Simulated internal DB — required fields always present
    private String getNameFromDb(String customerId) {
        return "SAV2001".equals(customerId) ? "Rajesh Kumar" : null;
    }

    private String getEmailFromDb(String customerId) {
        return "SAV2001".equals(customerId) ? "rajesh@bank.com" : null;
    }

    // Simulated external API — optional fields may be null
    private String getPhoneFromApi(String customerId) {
        return "SAV2001".equals(customerId) ? "+91-9876543210" : null;  // might be null
    }

    private Integer getCreditScoreFromApi(String customerId) {
        return "SAV2001".equals(customerId) ? 780 : null;  // might be null
    }

    public CustomerProfile buildProfile(String customerId) {

        // ═══ REQUIRED DATA: Optional.of() — null means BUG! ═══
        String name;
        try {
            name = Optional.of(getNameFromDb(customerId))  // of() — MUST be non-null
                .get();
        } catch (NullPointerException e) {
            log.error(" BUG: name should NEVER be null for customer {}", customerId);
            name = "BUG: name was null!";
        }

        String email;
        try {
            email = Optional.of(getEmailFromDb(customerId)).get();
        } catch (NullPointerException e) {
            log.error(" BUG: email should NEVER be null for customer {}", customerId);
            email = "BUG: email was null!";
        }

        // ═══ OPTIONAL DATA: Optional.ofNullable() — null means "not available" ═══
        String phone = Optional.ofNullable(getPhoneFromApi(customerId))
            .orElse("Not provided");  // null → "Not provided" (graceful)

        String creditScore = Optional.ofNullable(getCreditScoreFromApi(customerId))
            .map(score -> score + " (" + (score >= 700 ? "GOOD" : "POOR") + ")")
            .orElse("Score unavailable");  // null → "Score unavailable"

        return new CustomerProfile(customerId, name, email, phone, creditScore,
            "of() for required (null=bug) | ofNullable() for optional (null=absent)");
    }
}
