package com.bank.profile.service;

import org.junit.jupiter.api.Test;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;

class OfVsOfNullableTest {

    @Test
    void ofThrowsNpeOnNull() {
        assertThatThrownBy(() -> Optional.of(null))
            .isInstanceOf(NullPointerException.class);
    }

    @Test
    void ofWrapsNonNull() {
        Optional<String> opt = Optional.of("RELIANCE");
        assertThat(opt).isPresent();
        assertThat(opt.get()).isEqualTo("RELIANCE");
    }

    @Test
    void ofNullableReturnsEmptyForNull() {
        Optional<String> opt = Optional.ofNullable(null);
        assertThat(opt).isEmpty();
    }

    @Test
    void ofNullableWrapsNonNull() {
        Optional<String> opt = Optional.ofNullable("TCS");
        assertThat(opt).contains("TCS");
    }

    @Test
    void ofIsForRequiredValues() {
        // Service returns non-null — of() detects bugs
        String definitelyNotNull = "Rajesh Kumar";
        Optional<String> opt = Optional.of(definitelyNotNull);  // safe
        assertThat(opt).contains("Rajesh Kumar");
    }

    @Test
    void ofNullableIsForExternalData() {
        // External API might return null — ofNullable() handles it
        String maybeNull = null;  // simulate API response
        String result = Optional.ofNullable(maybeNull).orElse("Unknown");
        assertThat(result).isEqualTo("Unknown");
    }

    @Test
    void patternConvertLegacyNullToOptional() {
        // Legacy method returns null:
        String legacyResult = null;  // simulate old DAO

        // Convert to Optional at the boundary:
        Optional<String> opt = Optional.ofNullable(legacyResult);
        assertThat(opt).isEmpty();

        // Now use Optional API safely:
        String safe = opt.map(String::toUpperCase).orElse("DEFAULT");
        assertThat(safe).isEqualTo("DEFAULT");
    }
}
